{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a close retinoid analog, has an absolute oral bioavailability of approximately 60% (range 36-95%) after a 50 mg oral dose with food versus IV, supporting retinoid F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etretinate, a neutral lipophilic retinoid ester, has an absolute oral bioavailability of about 40% (range 30-70%) versus IV, supporting that the lipophilic retinoid scaffold is orally bioavailable above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin (13-cis-retinoic acid) has an estimated systemic bioavailability of 40% at 1 mg/kg/day, supporting the retinoid class reaching F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans retinoic acid oral bioavailability was estimated at no more than 25-30% in healthy volunteers, still above the 20% threshold and relevant to the retinoic acid-derived amide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "One report describes 13-cis-retinoic acid as having low absolute bioavailability with significant gut degradation; this is the main contrary evidence, but it is not quantitatively shown to be below 20% and conflicts with other retinoid data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Fenretinide is a lipophilic retinoid amide; close retinoid analogs (tretinoin, isotretinoin, acitretin, etretinate) have oral bioavailability estimates of about 25-60%, all above the 20% threshold. The single low absolute report for 13-cis-retinoic acid is not quantitatively below 20% and is outweighed. Predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide (4-HPR) with an IV comparator is present in the provided records.",
    "Fenretinide-specific first-pass metabolism and food/formulation effects are not directly captured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

